describe('Horizontal Scrolling Disabled on Main Layout', () => {
  beforeEach(() => {
    cy.visit('/main-layout');
  });

  it('should disable horizontal scrolling on main layout when viewport is mobile size', () => {
    // Set viewport to mobile size
    cy.viewport('iphone-x');

    // Verify main content is visible and scrollable vertically
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="main-content"]').should('have.height', 'auto');

    // Attempt to scroll horizontally by clicking on an element and dragging
    cy.get('[data-testid="main-content"]').then(($content) => {
      const scrollLeft = $content[0].scrollLeft;
      const scrollWidth = $content[0].scrollWidth;

      // Verify scrollLeft is 0 (no horizontal offset)
      expect(scrollLeft).to.equal(0);

      // Verify scrollWidth is equal to clientWidth (no overflow)
      expect(scrollWidth).to.equal($content[0].clientWidth);
    });

    // Verify no horizontal scrollbar is visible
    cy.get('[data-testid="horizontal-scrollbar"]').should('not.exist');

    // Verify vertical scrolling is still functional
    cy.get('[data-testid="main-content"]').scrollTo('bottom');
    cy.get('[data-testid="footer"]').should('be.visible');
  });

  it('should allow horizontal scrolling when viewport is desktop size', () => {
    // Set viewport to desktop size
    cy.viewport('desktop');

    // Verify horizontal scrollbar is visible on desktop
    cy.get('[data-testid="horizontal-scrollbar"]').should('be.visible');

    // Verify main content has horizontal overflow
    cy.get('[data-testid="main-content"]').then(($content) => {
      const scrollLeft = $content[0].scrollLeft;
      const scrollWidth = $content[0].scrollWidth;

      // Verify scrollWidth is greater than clientWidth
      expect(scrollWidth).to.be.greaterThan($content[0].clientWidth);

      // Verify scrollLeft is 0 initially
      expect(scrollLeft).to.equal(0);
    });

    // Verify horizontal scrolling is possible
    cy.get('[data-testid="main-content"]').scrollTo('right', 500);
    cy.get('[data-testid="main-content"]').should('have.scrollLeft', 500);

    // Verify vertical scrolling is still functional
    cy.get('[data-testid="main-content"]').scrollTo('bottom');
    cy.get('[data-testid="footer"]').should('be.visible');
  });
});
